function roundTrip(root: TreeNode | null): TreeNode | null {
  const serialize = (node: TreeNode | null): string => {
    const out: string[] = [];
    const write = (n: TreeNode | null): void => {
      if (!n) { out.push("#"); return; }
      out.push(String(n.val));
      write(n.left);
      write(n.right);
    };
    write(node);
    return out.join(",");
  };
  const deserialize = (data: string): TreeNode | null => {
    const tokens = data.split(",");
    let i = 0;
    const read = (): TreeNode | null => {
      const tok = tokens[i++];
      if (tok === "#") return null;
      const n = new TreeNode(Number(tok));
      n.left = read();  // preorder: the whole left subtree comes next
      n.right = read();
      return n;
    };
    return read();
  };
  return deserialize(serialize(root));
}

