function roundTrip(root: TreeNode | null): TreeNode | null {
  const serialize = (node: TreeNode | null): string => {
    const out: string[] = [], queue: (TreeNode | null)[] = [node];
    for (let i = 0; i < queue.length; i++) {
      const n = queue[i];
      if (!n) { out.push("#"); continue; }
      out.push(String(n.val));
      queue.push(n.left, n.right);
    }
    return out.join(",");
  };
  const deserialize = (data: string): TreeNode | null => {
    const tokens = data.split(",");
    if (tokens[0] === "#") return null;
    const top = new TreeNode(Number(tokens[0]));
    const queue: TreeNode[] = [top];
    let t = 1;
    for (let h = 0; h < queue.length; h++) {
      const n = queue[h];
      const l = tokens[t++], r = tokens[t++]; // the next two tokens are this node's children
      if (l !== "#") queue.push(n.left = new TreeNode(Number(l)));
      if (r !== "#") queue.push(n.right = new TreeNode(Number(r)));
    }
    return top;
  };
  return deserialize(serialize(root));
}

