class Solution:
    def roundTrip(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        def serialize(node):
            out, queue = [], deque([node])
            while queue:
                n = queue.popleft()
                if not n:
                    out.append("#")
                    continue
                out.append(str(n.val))
                queue.append(n.left)
                queue.append(n.right)
            return ",".join(out)

        def deserialize(data):
            tokens = data.split(",")
            if tokens[0] == "#":
                return None
            top = TreeNode(int(tokens[0]))
            queue, t = deque([top]), 1
            while queue:
                n = queue.popleft()
                l, r = tokens[t], tokens[t + 1]  # the next two tokens are this node's children
                t += 2
                if l != "#":
                    n.left = TreeNode(int(l))
                    queue.append(n.left)
                if r != "#":
                    n.right = TreeNode(int(r))
                    queue.append(n.right)
            return top

        return deserialize(serialize(root))

